lfs_size_t read_size = lfs->cfg->read_size;
    lfs_size_t block_size = lfs->cfg->block_size;
    lfs_size_t remaining = size;
    lfs_off_t current_off = off;
    lfs_block_t current_block = block;

    // Check if data is already in program cache
    if (pcache->block == current_block && current_off >= pcache->off &&
        current_off < pcache->off + pcache->size) {
        lfs_size_t overlap = pcache->off + pcache->size - current_off;
        if (overlap > remaining) overlap = remaining;
        int cmp = memcmp((uint8_t*)pcache->buffer + (current_off - pcache->off), 
                         (uint8_t*)buffer, overlap);
        if (cmp != 0) {
            return cmp < 0 ? LFS_CMP_LT : LFS_CMP_GT;
        }
        remaining -= overlap;
        current_off += overlap;
        buffer = (uint8_t*)buffer + overlap;
    }

    // Check if data is in read cache
    if (rcache->block == current_block && current_off >= rcache->off &&
        current_off < rcache->off + rcache->size) {
        lfs_size_t overlap = rcache->off + rcache->size - current_off;
        if (overlap > remaining) overlap = remaining;
        int cmp = memcmp((uint8_t*)rcache->buffer + (current_off - rcache->off), 
                         (uint8_t*)buffer, overlap);
        if (cmp != 0) {
            return cmp < 0 ? LFS_CMP_LT : LFS_CMP_GT;
        }
        remaining -= overlap;
        current_off += overlap;
        buffer = (uint8_t*)buffer + overlap;
    }

    // Read remaining data in chunks
    while (remaining > 0) {
        lfs_size_t read_size_eff = lfs_min(remaining, read_size);
        lfs_size_t read_offset = current_off % read_size;
        lfs_block_t read_block = current_block;
        lfs_off_t read_block_off = current_off - (current_off % read_size);

        // Ensure read cache is loaded for this region
        if (rcache->block != read_block || rcache->off > read_block_off ||
            rcache->off + rcache->size < read_block_off + read_size_eff) {
            int err = lfs_bd_read(lfs, rcache, read_block, read_block_off, rcache->buffer, read_size);
            if (err) {
                return err;
            }
            rcache->block = read_block;
            rcache->off = read_block_off;
            rcache->size = read_size;
        }

        // Compare the read data with buffer
        int cmp = memcmp((uint8_t*)rcache->buffer + read_offset, 
                         (uint8_t*)buffer, read_size_eff);
        if (cmp != 0) {
            return cmp < 0 ? LFS_CMP_LT : LFS_CMP_GT;
        }

        remaining -= read_size_eff;
        current_off += read_size_eff;
        buffer = (uint8_t*)buffer + read_size_eff;

        // Handle block boundary crossing
        if (current_off >= block_size) {
            current_off -= block_size;
            current_block++;
        }
    }

    return LFS_CMP_EQ;

